const body = $input.first().json.body || {};
const startTime = Date.now();

// Extract fields
const imageUrl = body.image_url || null;
const imageData = body.image_data || null;
const userRequest = body.user_request || '';
const domain = body.domain || 'general';
const availableTools = body.available_tools || [];

const errors = [];

// Must have either image_url or image_data
if (!imageUrl && !imageData) {
  errors.push('Either image_url or image_data (base64) is required');
}

// user_request is required
if (!userRequest || typeof userRequest !== 'string' || userRequest.trim().length === 0) {
  errors.push('user_request (non-empty string) is required');
}

// available_tools should be an array
if (!Array.isArray(availableTools) || availableTools.length === 0) {
  errors.push('available_tools (non-empty array) is required');
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join('; '),
        status: 'BAD_REQUEST'
      },
      startTime
    }
  };
}

// Determine image source
let imageSource = 'url';
let imageContent = imageUrl;
if (imageData && !imageUrl) {
  imageSource = 'base64';
  imageContent = imageData;
}

return {
  json: {
    valid: true,
    startTime,
    image_url: imageUrl,
    image_data: imageData,
    image_source: imageSource,
    user_request: userRequest.trim(),
    domain,
    available_tools: availableTools
  }
};

