={{ (() => {
  const data = $json;
  const tools = data.available_tools.join(', ');
  const domain = data.domain;

  const systemPrompt = `Tu es un analyseur de contenu intelligent. Tu analyses une image et une requête utilisateur pour déterminer:
1. Le type de contenu (content_type)
2. S'il y a du texte visible (has_text)
3. Le type de texte si présent (text_type)
4. Les éléments détectés (detected_items)
5. La langue détectée (language)
6. Un pipeline d'actions à exécuter

Domaine: ${domain}
Outils disponibles: ${tools}

RÈGLES IMPORTANTES:
- Réponds UNIQUEMENT en JSON valide
- content_type: "food_photo" | "handwritten_recipe" | "printed_recipe" | "document_pdf" | "screenshot" | "unknown"
- text_type: "handwritten" | "printed" | "mixed" | "none"
- on_fail: "abort" | "skip" | "fallback"
- Chaque step du pipeline doit utiliser un outil de la liste available_tools
- Utilise "$step_N.field" pour référencer le résultat d'un step précédent

Format de réponse:
{
  "analysis": {
    "content_type": "...",
    "has_text": true/false,
    "text_type": "...",
    "detected_items": ["item1", "item2"],
    "language": "fr" | "en" | null
  },
  "pipeline": [
    { "step": 1, "tool": "tool.name", "on_fail": "abort", "reason": "explication" },
    { "step": 2, "tool": "autre.tool", "input": "$step_1.result", "on_fail": "skip", "reason": "explication" }
  ],
  "confidence": 0.0-1.0
}`;

  const userPrompt = `Requête utilisateur: "${data.user_request}"

Analyse cette image et détermine le meilleur pipeline d'actions.`;

  // Build messages with image
  const imageContent = data.image_source === 'url' 
    ? { type: 'image_url', image_url: { url: data.image_url } }
    : { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${data.image_data}` } };

  return JSON.stringify({
    model: 'gpt-4o',
    max_tokens: 1000,
    temperature: 0.2,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: [
        { type: 'text', text: userPrompt },
        imageContent
      ]}
    ]
  });
})() }}

